import fs from 'node:fs'; import c from 'node:crypto'; import { execFile } from 'node:child_process';
const D=process.cwd(),PH=process.argv[2],RUB=process.argv[3];const F=JSON.parse(fs.readFileSync(`label-freeze-${PH}.json`)).hashes;
for(const [f,h] of Object.entries(F))if(c.createHash('sha256').update(fs.readFileSync(f)).digest('hex')!==h)throw Error('freeze mismatch '+f);
const ids=Object.keys(F).filter(f=>f.startsWith('blind/')).map(f=>f.slice(6,-3));
const ext=s=>{const e=s.lastIndexOf('\ntokens used');const b=e>0?s.slice(0,e):s;let i=b.lastIndexOf('\n{');while(i>=0){try{return JSON.parse(b.slice(i+1).trim())}catch{i=b.lastIndexOf('\n{',i-1)}}return null;};
const run=id=>new Promise(res=>{const out=`labels/codex/${id}.json`;if(fs.existsSync(out))return res('skip');
 const p=execFile('codex',['exec','-C',D,'-s','read-only','-'],{maxBuffer:1e8,timeout:900000},(e,so,se)=>{const s=String(so)+String(se);fs.writeFileSync(`labels/codex/${id}.log`,s);const o=ext(String(so));if(o){fs.writeFileSync(out,JSON.stringify(o,null,1));res('ok')}else res('FAIL')});
 p.stdin.end(`Read ONLY these files in ${D} and nothing else in the repository: labeler-prompt.md, blind/${id}.md, ${RUB}. The first is your instructions, then the conversation, then the rubric. Follow them exactly. Output only the JSON object.\n`);});
const r=await Promise.all(ids.map(run));console.log(r.join(' '));
EOF
